private static UIElement Build_muipage(string sampleDirectory)
{
var control = new MUIPage { ShowBorder = true, Height = "7" };
control.Children.Add(new TextBlock
{
    Text = "Library",
    ShowBorder = false, Height = "1"
});
control.Children.Add(new Button { Text = "Open library", Y = "2", Height = "3" });
return control;
}

private static UIElement Build_textblock(string sampleDirectory)
{
var control = new TextBlock
{
    Text = "Now playing\nExample track",
    Width = "42", Height = "5", ShowBorder = true,
    TextAlignment = Alignment.TopLeft
};
return control;
}

private static UIElement Build_textbox(string sampleDirectory)
{
var control = new TextBox
{
    Label = "Display name", Text = "Melon listener",
    Height = "5", Width = "42", MaxLength = 64
};
control.OnEnter = (text, input) => input.Label = $"Hello, {text}";
return control;
}

private static UIElement Build_button(string sampleDirectory)
{
var control = new Button { Text = "Save changes", Width = "32", Height = "3" };
control.OnPressed = () => control.Text = "Saved";
return control;
}

private static UIElement Build_buttonpanel(string sampleDirectory)
{
var control = new ButtonPanel { Width = "42", Height = "2", MaxLines = 2 };
control.Children.Add(new Button { Text = "Play" });
control.Children.Add(new Button { Text = "Queue" });
control.Children.Add(new Button { Text = "More information" });
return control;
}

private static UIElement Build_optionsmenu(string sampleDirectory)
{
var control = new OptionsMenu { MenuName = "Library", Width = "42", Height = "7" };
control.Options.Add(new MenuItem("Albums", () => { }));
control.Options.Add(new MenuItem("Artists", () => { }));
control.Options.Add(new MenuItem("Downloads", null) { IsEnabled = false });
return control;
}

private static UIElement Build_overflowmenu(string sampleDirectory)
{
var actions = new List<Button>
{
    new() { Text = "Play next" },
    new() { Text = "Add to playlist" }
};
var control = new OverflowMenu(actions) { Width = "42", Height = "5" };
return control;
}

